    private void HandleProc(string aLabel)
    {
        string l_Loc;
        int l_Idx;
        IJclStringList l_Params;
        TFURQActionModifier l_AM;
    
        l_Params = JclStringList;
        if (ParseLocAndParams(aLabel, l_Loc, l_Params, l_AM) != ( - 1))
        {
            throw new EFURQRunTimeError(sBadLocationSyntax);
        }
        if (l_AM != amNone)
        {
            throw new EFURQRunTimeError(sBadLocationSyntax);
        }
        l_Idx = f_CurContext.Code.Labels.IndexOf(l_Loc);
        if (l_Idx >= 0)
        {
            ApplyParams(l_Idx, l_Params);
            f_CurContext.ExecuteProc(l_Idx);
            if (global::furqTypesModule.EnsureReal(f_CurContext.Variables[cDOSURQCountVar]) != 0)
            {
                f_CurContext.IncLocationCount(l_Idx);
            }
        }
        else
        {
            EvaluateParams(l_Params);
            if (!f_CurContext.SystemProc(l_Loc, l_Params))
            {
                throw EFURQRunTimeError.CreateFmt(sNoLocationFound, new HashSet<int>(new int[] { (int)(l_Loc) }));
            }
        }
    }
    
