    protected void ParseOperators()
    {
        string l_SrcLine;
        void GetSrcLine()
        {
            string l_Str;
            void SkipBlanks()
            {
                while (!EOF & (Trim(CurLine) == ""))
                {
                    IncLine();
                }
            }
        
        
            l_SrcLine = "";
            while (!EOF)
            {
                SkipBlanks();
                if (!EOF)
                {
                    l_Str = TrimLeft(CurLine);
                    if (l_SrcLine == "")
                    {
                        if (AnsiStartsStr(":", l_Str))
                        {
                            IncLine();
                            continue;
                        }
                        if (AnsiStartsStr("_", l_Str))
                        {
                            Delete(l_Str, 1, 1);
                            if (Trim(l_Str) == "")
                            {
                                IncLine();
                                SkipBlanks();
                                continue;
                            }
                        }
                        l_SrcLine = l_Str;
                        IncLine();
                    }
                    else
                    {
                        if (~AnsiStartsStr("_", l_Str))
                        {
                            break;
                        }
                        Delete(l_Str, 1, 1);
                        l_SrcLine = (l_SrcLine + l_Str);
                        IncLine();
                    }
                }
            }
        }
    
        TFURQOperator ParseStringToOps(in string aSrc)
        {
            var __captured1_aSrc = aSrc;
            TFURQOperator l_ResOp;
            TFURQOperator l_Op;
            TfurqLexer l_Lexer;
            int l_IFCount;
            string l_Cond;
            string l_Then;
            string l_Else;
            int l_Start;
            bool l_IsFirstTokenInOperator;
            bool l_IFDetected;
            TFURQOperator __localResult1;
            string GetSubstrBeforeToken()
            {
                string __localResult2;
                __localResult2 = Copy(__captured1_aSrc, l_Start, (l_Lexer.TokenStart - l_Start));
                l_Start = l_Lexer.TokenEnd;
                return __localResult2;
            }
        
            string GetSubstrAfterToken()
            {
                string __localResult2;
                __localResult2 = Copy(__captured1_aSrc, l_Start, (l_Lexer.TokenEnd - l_Start));
                l_Start = l_Lexer.TokenEnd;
                return __localResult2;
            }
        
            void AddOp(TFURQOperator aOp)
            {
                if (l_ResOp == null)
                {
                    l_Op = aOp;
                    l_ResOp = aOp;
                }
                else
                {
                    l_Op.Next = aOp;
                    l_Op = l_Op.Next;
                }
            }
        
            void AddOpStr(in string aOpSrc)
            {
                string l_OpSrc;
            
                l_OpSrc = TrimLeft(aOpSrc);
                if (l_OpSrc != "")
                {
                    AddOp(TFURQOperator.Create(l_OpSrc));
                }
            }
        
        
            __localResult1 = null;
            if (aSrc == "")
            {
                return __localResult1;
            }
            l_ResOp = null;
            l_Lexer = TfurqLexer.Create;
            try
            {
                l_Lexer.DetectStrings = false;
                l_Lexer.Source = aSrc;
                l_IFCount = 0;
                l_Start = 1;
                l_IsFirstTokenInOperator = true;
                l_IFDetected = false;
                while (true)
                {
                    switch (l_Lexer.Token)
                    {
                        case etIF:
                            if (l_IsFirstTokenInOperator)
                            {
                                if (l_IFCount == 0)
                                {
                                    l_Cond = "";
                                    l_Then = "";
                                    l_Else = "";
                                    l_Start = l_Lexer.TokenEnd;
                                    l_IFDetected = true;
                                }
                                l_IFCount++;
                            }
                            break;
                        case etThen:
                            if (l_IFDetected)
                            {
                                if (l_IFCount == 1)
                                {
                                    l_Cond = GetSubstrBeforeToken;
                                }
                                l_IsFirstTokenInOperator = true;
                            }
                            break;
                        case etElse:
                            if (l_IFDetected)
                            {
                                if (l_IFCount == 1)
                                {
                                    l_Then = GetSubstrBeforeToken;
                                    l_Else = Copy(aSrc, l_Lexer.TokenEnd, MaxInt);
                                    if (l_Cond == "")
                                    {
                                        throw new EFURQRunTimeError(sIfWithoutThen);
                                    }
                                    AddOp(TFURQCondition.Create(l_Cond, ParseStringToOps(l_Then), ParseStringToOps(l_Else)));
                                    break;
                                }
                                Dec(l_IFCount);
                                l_IsFirstTokenInOperator = true;
                            }
                            break;
                        case etAmpersand:
                            if (!l_IFDetected)
                            {
