    private string UnfoldSubst(in string aString)
    {
        var __captured0_aString = aString;
        int l_CurPos;
        int l_TempPos;
        string l_Subst;
        byte l_SubMode;
        char C;
        int l_InCount;
        TfurqExprEvaluator l_Eval;
        int l_CharCode;
        string result;
        char GetChar(int aIndex)
        {
