            }
            return __localResult1;
        }
    
    
        result = "";
        l_Eval = null;
        l_CurPos = 1;
        try
        {
            while (true)
            {
                l_TempPos = PosEx("#", aString, l_CurPos);
                if (l_TempPos > 0)
                {
                    result = (result + Copy(aString, l_CurPos, (l_TempPos - l_CurPos)));
                    l_CurPos = (l_TempPos + 1);
                    switch (GetChar(l_CurPos))
                    {
                        case '%':
                            l_SubMode = smString;
                            l_CurPos++;
                            break;
                        case '#':
                            l_SubMode = smCharCode;
                            l_CurPos++;
                            break;
                        default:
                            l_SubMode = smNumber;
                            break;
                    }
                    l_Subst = "";
                    l_InCount = 0;
                    C = GetChar(l_CurPos);
                    while (C != '\0')
                    {
                        switch (C)
                        {
                            case '$':
                                if (l_InCount == 0)
                                {
                                    break;
                                }
                                else
                                {
                                    Dec(l_InCount);
                                }
                                break;
                            case '#':
                                l_InCount++;
