                    }
                    l_CurPos++;
                    l_Subst = UnfoldSubst(l_Subst);
                    if ((l_SubMode == smNumber) & (l_Subst == ""))
                    {
                        result = (result + " ");
                    }
                    else
                    {
                        if ((l_SubMode == smNumber) & (l_Subst == "/"))
                        {
